{
  "name": "安道尔科学相机",
  "name_en": "Andor Scientific Camera",
  "manufacturer": "Andor",
  "description": "安道尔科学相机是一类高灵敏度实验室探测器，通常带有热电制冷功能，可用于低光信号检测与光谱采集。根据现有证据，该设备支持积分时间、快门、风扇、高增益、垂直分箱及探测器温度控制，常作为科研光谱系统中的探测器使用。",
  "description_en": "An Andor scientific camera is a high-sensitivity laboratory detector, typically with thermoelectric cooling, used for low-light detection and spectral acquisition. Based on the available evidence, it supports integration time, shutter, fan, high-gain mode, vertical binning, and detector temperature control, and is commonly used as the detector in research spectroscopy systems.",
  "tag_hints": [
    "scientific camera",
    "spectroscopy detector",
    "thermoelectric cooling",
    "low-light detection",
    "vertical binning",
    "integration time control",
    "shutter control"
  ],
  "actions": [
    {
      "action_name": "auto-not_implemented",
      "description": "未实现功能的占位操作",
      "description_en": "placeholder for an unimplemented function"
    },
    {
      "action_name": "auto-high_gain_mode_enable",
      "description": "启用或禁用高增益模式",
      "description_en": "enable or disable high-gain mode"
    },
    {
      "action_name": "auto-set_fan_enable",
      "description": "启用或禁用冷却风扇",
      "description_en": "enable or disable the cooling fan"
    },
    {
      "action_name": "auto-check_result",
      "description": "检查设备命令返回结果",
      "description_en": "check the result returned by a device command"
    },
    {
      "action_name": "auto-connect",
      "description": "连接并初始化相机",
      "description_en": "connect to and initialize the camera"
    },
    {
      "action_name": "auto-set_take_one_request",
      "description": "设置单次采集请求",
      "description_en": "define a single-acquisition request"
    },
    {
      "action_name": "auto-set_vertical_binning",
      "description": "设置垂直分箱或垂直感兴趣区域",
      "description_en": "set vertical binning or the vertical region of interest"
    },
    {
      "action_name": "auto-save_config",
      "description": "保存设备配置",
      "description_en": "save device configuration"
    },
    {
      "action_name": "auto-update_config_from_eeprom",
      "description": "根据EEPROM更新设备配置",
      "description_en": "update device configuration from EEPROM"
    },
    {
      "action_name": "auto-acquire_data",
      "description": "采集光谱数据",
      "description_en": "acquire spectral data"
    },
    {
      "action_name": "auto-set_shutter_enable",
      "description": "打开或关闭快门",
      "description_en": "enable or disable the shutter"
    },
    {
      "action_name": "auto-set_integration_time_ms",
      "description": "设置积分时间",
      "description_en": "set integration time"
    },
    {
      "action_name": "auto-init_tec_setpoint",
      "description": "初始化热电制冷设定温度",
      "description_en": "initialize the thermoelectric cooler temperature setpoint"
    },
    {
      "action_name": "auto-toggle_tec",
      "description": "开启或关闭热电制冷器",
      "description_en": "turn the thermoelectric cooler on or off"
    },
    {
      "action_name": "auto-set_tec_setpoint",
      "description": "设置热电制冷设定温度",
      "description_en": "set the thermoelectric cooler temperature setpoint"
    },
    {
      "action_name": "auto-init_detector_area",
      "description": "初始化探测器区域",
      "description_en": "initialize the detector area"
    },
    {
      "action_name": "auto-init_detector_speed",
      "description": "初始化探测器读出速度设置",
      "description_en": "initialize detector readout speed settings"
    },
    {
      "action_name": "auto-set_scans_to_average",
      "description": "设置平均扫描次数",
      "description_en": "set the number of scans to average"
    },
    {
      "action_name": "auto-load_error_codes",
      "description": "加载设备错误代码表",
      "description_en": "load the device error code table"
    },
    {
      "action_name": "auto-get_detector_temperature_degC",
      "description": "获取探测器温度",
      "description_en": "get detector temperature"
    },
    {
      "action_name": "auto-get_serial_number",
      "description": "获取序列号",
      "description_en": "get serial number"
    },
    {
      "action_name": "auto-get_error_code_long",
      "description": "获取错误代码详细说明",
      "description_en": "get long-form error code description"
    },
    {
      "action_name": "auto-get_error_code",
      "description": "获取错误代码说明",
      "description_en": "get error code description"
    }
  ]
}

